    if (e.key in keys) {
      keys[e.key] = null;
    }
  });

  // Render player and grid
  redraw();
});

// Redraw function
function redraw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw grid
  for (let x = 0; x < canvas.width; x += player.radius * 2) {
    ctx.beginPath('lines');
